<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Factura {{ $invoice->number }}</title><style>body{max-width:850px;margin:40px auto;color:#282828;font:14px Arial}header{display:flex;justify-content:space-between;border-bottom:3px solid #5d1c38;padding-bottom:22px}h1{color:#5d1c38}table{width:100%;border-collapse:collapse;margin-top:35px}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}.totals{margin:30px 0 0 auto;width:320px}.totals p{display:flex;justify-content:space-between}.total{font-size:20px;font-weight:bold;border-top:2px solid #5d1c38;padding-top:14px}</style></head><body><header><div><h1>MOLDPACK</h1><p>Dante Alighieri 1377, Don Torcuato<br>ventas@moldpack.com.ar</p></div><div><h2>Factura {{ $invoice->type }}</h2><strong>{{ $invoice->number }}</strong><p>{{ optional($invoice->issued_at)->format('d/m/Y') }}</p></div></header><section><h3>{{ $invoice->order->cliente->business_name ?: $invoice->order->cliente->name }}</h3><p>CUIT: {{ $invoice->order->cliente->tax_id ?: '—' }}<br>{{ $invoice->order->cliente->billing_address }}</p></section><table><thead><tr><th>Código</th><th>Producto</th><th>Cantidad</th><th>Precio</th><th>Subtotal</th></tr></thead><tbody>@foreach($invoice->order->items as $item)<tr><td>{{ $item->sku }}</td><td>{{ $item->name }}</td><td>{{ $item->quantity }}</td><td>${{ number_format($item->unit_price,2,',','.') }}</td><td>${{ number_format($item->line_total,2,',','.') }}</td></tr>@endforeach</tbody></table><div class="totals"><p><span>Subtotal</span><b>${{ number_format($invoice->subtotal,2,',','.') }}</b></p><p><span>IVA</span><b>${{ number_format($invoice->tax_total,2,',','.') }}</b></p><p class="total"><span>Total</span><b>${{ number_format($invoice->total,2,',','.') }}</b></p></div></body></html>
